#!/usr/bin/env node

const { Command } = require('commander');
const chalk = require('chalk');
const fs = require('fs-extra');
const path = require('path');

const GoiasScriptCompiler = require('../compiler');
const packageJson = require('../../package.json');

/**
 * CLI principal do GoiásScript
 * Implementa Command Pattern para diferentes comandos
 */
class GoiasScriptCLI {
  constructor() {
    this.program = new Command();
    this.compiler = new GoiasScriptCompiler();
    this.setupCommands();
  }

  /**
   * Configura todos os comandos disponíveis
   */
  setupCommands() {
    this.program
      .name('goiasscript')
      .description('Linguagem de programação baseada no dialeto goiano')
      .version(packageJson.version);

    // Comando principal: executar arquivo
    this.program
      .argument('[arquivo]', 'arquivo .gs para executar')
      .option('-c, --compiled', 'mostrar código JavaScript gerado')
      .option('-o, --output <arquivo>', 'salvar JavaScript em arquivo')
      .option('-w, --watch', 'observar arquivo e recompilar automaticamente')
      .option('-d, --debug', 'modo debug com informações extras')
      .option('--source-map', 'gerar source map')
      .action((arquivo, options) => {
        this.runFile(arquivo, options);
      });

    // Comando init
    this.program
      .command('init')
      .description('Inicializar projeto GoiásScript')
      .option('-n, --name <nome>', 'nome do projeto')
      .action((options) => {
        this.initProject(options);
      });

    // Comando validate
    this.program
      .command('validate <arquivo>')
      .description('Validar sintaxe de arquivo GoiásScript')
      .action((arquivo) => {
        this.validateFile(arquivo);
      });

    // Comando transpile
    this.program
      .command('transpile <arquivo>')
      .description('Transpilar arquivo para JavaScript')
      .option('-o, --output <arquivo>', 'arquivo de saída')
      .option('--source-map', 'gerar source map')
      .action((arquivo, options) => {
        this.transpileFile(arquivo, options);
      });

    // Comando docs
    this.program
      .command('docs')
      .description('Abrir documentação no navegador')
      .action(() => {
        this.openDocs();
      });
  }

  /**
   * Executa arquivo GoiásScript
   * @param {string} arquivo - Caminho do arquivo
   * @param {Object} options - Opções do comando
   */
  async runFile(arquivo, options = {}) {
    if (!arquivo) {
      console.log(chalk.yellow('Uso: goiasscript <arquivo.gs>'));
      console.log(chalk.blue('\\nExemplos:'));
      console.log('  goiasscript exemplo.gs');
      console.log('  goiasscript --compiled exemplo.gs');
      return;
    }

    try {
      const caminhoCompleto = path.resolve(arquivo);

      if (!await fs.pathExists(caminhoCompleto)) {
        console.error(chalk.red(`Arquivo não encontrado: ${arquivo}`));
        return;
      }

      if (!arquivo.endsWith('.gs')) {
        console.error(chalk.red('Arquivo deve ter extensão .gs'));
        return;
      }

      const codigo = await fs.readFile(caminhoCompleto, 'utf8');

      // Configurar compilador
      this.compiler = new GoiasScriptCompiler({
        debug: options.debug,
        sourceMap: options.sourceMap,
      });

      if (options.compiled) {
        // Apenas transpila e mostra o resultado
        const resultado = this.compiler.compile(codigo, arquivo);

        if (resultado.success) {
          console.log(chalk.green('📄 Código JavaScript gerado:'));
          console.log(chalk.dim('─'.repeat(50)));
          console.log(resultado.javascript);
          console.log(chalk.dim('─'.repeat(50)));

          if (options.output) {
            await fs.writeFile(options.output, resultado.javascript);
            console.log(chalk.green(`✅ Salvo em: ${options.output}`));
          }
        } else {
          resultado.error.mostrarErro();
        }
      } else {
        // Executa o código
        console.log(chalk.blue(`🤠 Executando: ${arquivo}`));
        console.log(chalk.dim('─'.repeat(30)));

        await this.compiler.execute(codigo, arquivo);
      }

    } catch (error) {
      console.error(chalk.red('❌ Erro:'), error.message);
    }
  }

  /**
   * Inicializa projeto GoiásScript
   * @param {Object} options - Opções do comando
   */
  async initProject(options = {}) {
    const nome = options.name || 'meu-projeto-goiasscript';
    const diretorio = path.resolve(nome);

    try {
      // Criar estrutura de projeto
      await fs.ensureDir(diretorio);
      await fs.ensureDir(path.join(diretorio, 'src'));
      await fs.ensureDir(path.join(diretorio, 'exemplos'));

      // Criar package.json
      const packageJson = {
        name: nome,
        version: '1.0.0',
        description: 'Projeto em GoiásScript',
        main: 'src/main.gs',
        scripts: {
          start: 'goiasscript src/main.gs',
          dev: 'goiasscript --watch src/main.gs',
          build: 'goiasscript --compiled src/main.gs -o dist/main.js',
        },
        keywords: ['goiasscript'],
        author: '',
        license: 'MIT',
      };

      await fs.writeJson(path.join(diretorio, 'package.json'), packageJson, { spaces: 2 });

      // Criar arquivo principal
      const codigoMain = `// Meu primeiro projeto em GoiásScript!

uai saudacao é "Bão demais da conta, sô!";
prosa(saudacao);

presta_serviço exemploFuncao() {
  uai mensagem é "GoiásScript tá funcionando perfeitamente!";
  faz_favor mensagem;
}

prosa(exemploFuncao());
`;

      await fs.writeFile(path.join(diretorio, 'src', 'main.gs'), codigoMain);

      // Criar README
      const readme = `# ${nome}

Projeto criado com GoiásScript 🤠

## Como usar

\`\`\`bash
# Executar projeto
npm start

# Modo desenvolvimento
npm run dev

# Build para JavaScript
npm run build
\`\`\`

## Documentação

Visite a [documentação oficial](https://github.com/Gefferson-Souza/goiasscript) para aprender mais sobre GoiásScript.
`;

      await fs.writeFile(path.join(diretorio, 'README.md'), readme);

      console.log(chalk.green('🎉 Projeto criado com sucesso!'));
      console.log(chalk.blue(`📁 Diretório: ${diretorio}`));
      console.log(chalk.yellow('\\n📋 Próximos passos:'));
      console.log(`   cd ${nome}`);
      console.log('   npm start');

    } catch (error) {
      console.error(chalk.red('❌ Erro ao criar projeto:'), error.message);
    }
  }

  /**
   * Valida sintaxe de arquivo
   * @param {string} arquivo - Caminho do arquivo
   */
  async validateFile(arquivo) {
    try {
      const caminhoCompleto = path.resolve(arquivo);

      if (!await fs.pathExists(caminhoCompleto)) {
        console.error(chalk.red(`Arquivo não encontrado: ${arquivo}`));
        return;
      }

      const codigo = await fs.readFile(caminhoCompleto, 'utf8');
      const resultado = this.compiler.validate(codigo);

      if (resultado.valid) {
        console.log(chalk.green('✅ Sintaxe válida!'));
        console.log(chalk.blue(`📊 ${resultado.tokens.length} tokens encontrados`));
      } else {
        console.log(chalk.red('❌ Sintaxe inválida'));
        resultado.errors.forEach(erro => {
          if (erro.mostrarErro) {
            erro.mostrarErro();
          } else {
            console.error(chalk.red(erro.message));
          }
        });
      }

      if (resultado.warnings.length > 0) {
        console.log(chalk.yellow('⚠️  Avisos:'));
        resultado.warnings.forEach(warning => {
          console.log(chalk.yellow(`   ${warning}`));
        });
      }

    } catch (error) {
      console.error(chalk.red('❌ Erro na validação:'), error.message);
    }
  }

  /**
   * Transpila arquivo para JavaScript
   * @param {string} arquivo - Caminho do arquivo
   * @param {Object} options - Opções do comando
   */
  async transpileFile(arquivo, options = {}) {
    try {
      const caminhoCompleto = path.resolve(arquivo);

      if (!await fs.pathExists(caminhoCompleto)) {
        console.error(chalk.red(`Arquivo não encontrado: ${arquivo}`));
        return;
      }

      const codigo = await fs.readFile(caminhoCompleto, 'utf8');

      this.compiler = new GoiasScriptCompiler({
        sourceMap: options.sourceMap,
      });

      const resultado = this.compiler.compile(codigo, arquivo);

      if (resultado.success) {
        const outputPath = options.output || arquivo.replace('.gs', '.js');

        await fs.writeFile(outputPath, resultado.javascript);

        if (resultado.sourceMap && options.sourceMap) {
          await fs.writeJson(outputPath + '.map', resultado.sourceMap);
        }

        console.log(chalk.green('✅ Transpilaçao concluída!'));
        console.log(chalk.blue(`📄 Arquivo: ${outputPath}`));
        console.log(chalk.dim(`📊 Estatísticas: ${resultado.stats.originalLines} → ${resultado.stats.compiledLines} linhas`));
      } else {
        resultado.error.mostrarErro();
      }

    } catch (error) {
      console.error(chalk.red('❌ Erro na transpilação:'), error.message);
    }
  }

  /**
   * Abre documentação
   */
  openDocs() {
    const { exec } = require('child_process');
    const url = 'https://github.com/Gefferson-Souza/goiasscript#readme';

    console.log(chalk.blue('📚 Abrindo documentação...'));
    console.log(chalk.dim(`URL: ${url}`));

    // Tentar abrir no navegador padrão
    const command = process.platform === 'win32' ? 'start' : 
      process.platform === 'darwin' ? 'open' : 'xdg-open';

    exec(`${command} ${url}`, (error) => {
      if (error) {
        console.log(chalk.yellow('Não foi possível abrir automaticamente.'));
        console.log(chalk.blue(`Acesse: ${url}`));
      }
    });
  }

  /**
   * Inicia o CLI
   */
  run() {
    // Tratamento de erros não capturados
    process.on('unhandledRejection', (error) => {
      console.error(chalk.red('❌ Erro não tratado:'), error.message);
      if (error.stack) {
        console.error(chalk.dim(error.stack));
      }
      process.exit(1);
    });

    this.program.parse();
  }
}

// Executar CLI se chamado diretamente
if (require.main === module) {
  const cli = new GoiasScriptCLI();
  cli.run();
}

module.exports = GoiasScriptCLI;

const SimpleTranspiler = require('./compiler/simpleTranspiler');
const GoianoBuiltins = require('./goianoMethods/GoianoBuiltins');

// Optional feature modules — gracefully degrade when absent (v1.5 slim build).
// When the source files exist, full v2 behavior is preserved; when they're
// archived for v1.5, the compiler falls back to no-op stubs so transpilation
// keeps working without type checking, module resolution, or JIT optimization.
function loadOptional(modulePath, fallback) {
  try {
    return require(modulePath);
  } catch (err) {
    if (err && err.code === 'MODULE_NOT_FOUND') {
      return fallback;
    }
    throw err;
  }
}

class NoopTypeAnalyzer {
  analyze() {
    return { typeCount: 0, symbolTable: {}, hasTypeErrors: false, warnings: [], errors: [] };
  }
}

class NoopModuleResolver {
  resolveModules(code) {
    return { code, hasModules: false, imports: [], exports: [], dependencies: [], warnings: [] };
  }
  clearCache() {}
  generateDependencyReport() {
    return { totalModules: 0, modules: [] };
  }
  moduleExists() {
    return true;
  }
  detectCircularDependencies() {
    return null;
  }
}

class NoopJITCompiler {
  shouldApplyJIT() {
    return false;
  }
  compile(code) {
    return code;
  }
  generatePerformanceReport() {
    return null;
  }
  clearCache() {}
  setOptimizations() {}
  setThreshold() {}
  getHotSpots() {
    return [];
  }
}

const TypeAnalyzer = loadOptional('./types/TypeAnalyzer', NoopTypeAnalyzer);
const ModuleResolver = loadOptional('./modules/ModuleResolver', NoopModuleResolver);
const GoianoJITCompiler = loadOptional('./performance/JITCompiler', NoopJITCompiler);

/**
 * Main GoiásScript Compiler
 * Integrates transpilation, type checking, and module resolution
 */
class GoiasScriptCompiler {
  constructor(options = {}) {
    this.transpiler = new SimpleTranspiler(options);
    this.typeAnalyzer = new TypeAnalyzer();
    this.moduleResolver = new ModuleResolver();
    this.goianoBuiltins = new GoianoBuiltins();
    this.jitCompiler = new GoianoJITCompiler();
    this.options = {
      enableTypeChecking: true,
      enableModuleResolution: true,
      enableGoianoMethods: true,
      enableJIT: true,
      ...options,
    };
  }

  /**
   * Compile GoiásScript code to JavaScript
   * @param {string} code - GoiásScript source code
   * @param {string} fileName - Source file name
   * @returns {Object} Compilation result
   */
  compile(code, fileName = 'script.gs') {
    try {
      const result = {
        success: false,
        javascript: null,
        typeInfo: null,
        moduleInfo: null,
        warnings: [],
        errors: [],
      };

      // 1. Module Resolution (if enabled)
      let processedCode = code;
      if (this.options.enableModuleResolution) {
        const moduleResult = this.moduleResolver.resolveModules(code, fileName);
        processedCode = moduleResult.code;
        result.moduleInfo = {
          hasModules: moduleResult.hasModules,
          imports: moduleResult.imports,
          exports: moduleResult.exports,
          dependencies: moduleResult.dependencies,
        };
        result.warnings.push(...(moduleResult.warnings || []));
      }

      // 2. Type Analysis (if enabled)
      if (this.options.enableTypeChecking) {
        const typeResult = this.typeAnalyzer.analyze(processedCode, fileName);
        result.typeInfo = {
          typeCount: typeResult.typeCount,
          symbols: typeResult.symbolTable,
          hasTypeErrors: typeResult.hasTypeErrors,
        };
        result.warnings.push(...(typeResult.warnings || []));
        result.errors.push(...(typeResult.errors || []));
      }

      // 3. Transpilation
      const transpileResult = this.transpiler.transpile(processedCode, fileName);

      if (!transpileResult.success) {
        result.errors.push(transpileResult.error);
        return result;
      }

      result.javascript = transpileResult.code;
      result.warnings.push(...(transpileResult.warnings || []));

      // 4. JIT Optimization (if enabled)
      if (this.options.enableJIT) {
        const identifier = this._generateIdentifier(fileName, code);

        if (this.jitCompiler.shouldApplyJIT(result.javascript, identifier)) {
          result.javascript = this.jitCompiler.compile(result.javascript, identifier);
          result.jitOptimized = true;
          result.warnings.push({
            type: 'jit_optimization',
            message: `🔥 Código otimizado via JIT para "${identifier}"`,
          });
        }
      }

      result.success = true;
      return result;
    } catch (error) {
      return {
        success: false,
        javascript: null,
        typeInfo: null,
        moduleInfo: null,
        warnings: [],
        errors: [
          {
            type: 'compilation_error',
            message: `Erro na compilação: ${error.message}`,
            line: 0,
            column: 0,
          },
        ],
      };
    }
  }

  /**
   * Get available Goiano methods
   * @returns {Array} List of available Goiano methods
   */
  getGoianoMethods() {
    return this.goianoBuiltins.listarMetodosGoianos();
  }

  /**
   * Get available Goiano types
   * @returns {Array} List of available Goiano types
   */
  getGoianoTypes() {
    return this.goianoBuiltins.listarTiposGoianos();
  }

  /**
   * Clear module cache
   */
  clearModuleCache() {
    if (this.moduleResolver) {
      this.moduleResolver.clearCache();
    }
  }

  /**
   * Get module dependency report
   * @returns {Object} Dependency report
   */
  getModuleDependencyReport() {
    if (this.moduleResolver) {
      return this.moduleResolver.generateDependencyReport();
    }
    return { totalModules: 0, modules: [] };
  }

  /**
   * Check if a method is forbidden (non-Goiano)
   * @param {string} method - Method name to check
   * @returns {boolean} True if method is forbidden
   */
  isForbiddenMethod(method) {
    return this.goianoBuiltins.ehMetodoProibido(method);
  }

  /**
   * Validate GoiásScript code syntax
   * @param {string} code - GoiásScript source code
   * @param {string} fileName - Source file name
   * @returns {Object} Validation result
   */
  validate(code, fileName = 'script.gs') {
    try {
      // Use transpiler to validate syntax
      const transpileResult = this.transpiler.transpile(code, fileName);

      return {
        valid: transpileResult.success,
        errors: transpileResult.success ? [] : [transpileResult.error],
        tokens: transpileResult.tokens || [],
        warnings: transpileResult.warnings || [],
      };
    } catch (error) {
      return {
        valid: false,
        errors: [{ message: error.message, type: 'validation_error' }],
        tokens: [],
        warnings: [],
      };
    }
  }

  /**
   * Transpile code without execution
   * @param {string} code - GoiásScript source code
   * @param {string} fileName - Source file name
   * @returns {Object} Transpilation result
   */
  transpile(code, fileName = 'script.gs') {
    return this.compile(code, fileName);
  }

  /**
   * Get compilation statistics
   * @param {string} code - GoiásScript source code
   * @param {string} fileName - Source file name
   * @returns {Object} Compilation statistics
   */
  getCompilationStats(code, fileName = 'script.gs') {
    const result = this.compile(code, fileName);

    return {
      success: result.success,
      linesOfCode: code.split('\n').length,
      typeCount: result.typeInfo ? result.typeInfo.typeCount : 0,
      moduleCount: result.moduleInfo ? result.moduleInfo.dependencies.length : 0,
      warningCount: result.warnings.length,
      errorCount: result.errors.length,
      hasModules: result.moduleInfo ? result.moduleInfo.hasModules : false,
      hasTypes: result.typeInfo ? result.typeInfo.typeCount > 0 : false,
    };
  }

  /**
   * Execute compiled GoiásScript code
   * @param {string} code - GoiásScript source code
   * @param {string} fileName - Source file name
   * @returns {Object} Execution result
   */
  execute(code, fileName = 'script.gs') {
    try {
      const compileResult = this.compile(code, fileName);

      if (!compileResult.success) {
        return {
          success: false,
          error: compileResult.errors[0] || { message: 'Compilation failed' },
          output: null,
        };
      }

      // Execute compiled JavaScript in the local Node scope.
      // eval is intentional here: this method is called only by the CLI
      // (bin/goiasscript.js bota_pra_moer) on user-owned .gs files. The
      // browser playground (Fase 1) MUST NOT use this path — it has to
      // sandbox via new Function or Web Workers in an isolated iframe.
      // eslint-disable-next-line no-eval
      const result = eval(compileResult.javascript);

      return {
        success: true,
        output: result,
        error: null,
      };
    } catch (error) {
      return {
        success: false,
        error: { message: error.message, type: 'execution_error' },
        output: null,
      };
    }
  }

  /**
   * Transpile only (alias for transpile method)
   * @param {string} code - GoiásScript source code
   * @param {string} fileName - Source file name
   * @returns {string} JavaScript code
   */
  transpileOnly(code, fileName = 'script.gs') {
    const result = this.compile(code, fileName);
    return result.success ? result.javascript : null;
  }

  /**
   * Generate unique identifier for JIT caching
   * @private
   */
  _generateIdentifier(fileName, code) {
    const hash = code.split('').reduce((hash, char) => {
      return ((hash << 5) - hash + char.charCodeAt(0)) & 0xffffffff;
    }, 0);

    return `${fileName.replace(/[^\w]/g, '_')}_${Math.abs(hash)}`;
  }

  /**
   * Get JIT performance report
   */
  getJITReport() {
    return this.jitCompiler ? this.jitCompiler.generatePerformanceReport() : null;
  }

  /**
   * Clear JIT cache
   */
  clearJITCache() {
    if (this.jitCompiler) {
      this.jitCompiler.clearCache();
    }
  }

  /**
   * Configure JIT optimizations
   */
  configureJIT(options) {
    if (this.jitCompiler) {
      if (options.optimizations) {
        this.jitCompiler.setOptimizations(options.optimizations);
      }
      if (options.threshold) {
        this.jitCompiler.setThreshold(options.threshold);
      }
    }
  }

  /**
   * Get JIT hot spots
   */
  getJITHotSpots() {
    return this.jitCompiler ? this.jitCompiler.getHotSpots() : [];
  }

  /**
   * Compile with additional statistics
   * @param {string} code - GoiásScript source code
   * @param {string} fileName - Source file name
   * @returns {Object} Compilation result with stats
   */
  compileWithStats(code, fileName = 'script.gs') {
    const result = this.compile(code, fileName);

    if (result.success) {
      result.stats = {
        originalSize: code.length,
        compiledSize: result.javascript.length,
        originalLines: code.split('\n').length,
        compiledLines: result.javascript.split('\n').length,
      };
    }

    return result;
  }
}

module.exports = GoiasScriptCompiler;

const ErrorTranslator = require('../errors/errorTranslator');
const GoianoBuiltins = require('../goianoMethods/GoianoBuiltins');

/**
 * Transpiler simplificado do GoiásScript
 * Implementa substituições diretas para funcionar imediatamente
 */
class SimpleGoiasScriptTranspiler {
  constructor(options = {}) {
    this.errorTranslator = new ErrorTranslator();
    this.goianoBuiltins = new GoianoBuiltins();
    this.options = options;
  }

  /**
   * Transpiles GoiásScript code to JavaScript
   * @param {string} code - GoiásScript source code
   * @param {string} fileName - Source file name
   * @returns {Object} Transpilation result
   */
  transpile(code, fileName = 'script.gs') {
    try {
      // Basic syntax validation
      const syntaxErrors = this._validateSyntax(code);
      if (syntaxErrors.length > 0) {
        return {
          success: false,
          error: syntaxErrors[0],
          code: null,
        };
      }

      let jsCode = code;

      // Apply all substitutions
      jsCode = this._applySubstitutions(jsCode);

      // Check for forbidden non-Goiano methods
      const warnings = this._checkForbiddenMethods(jsCode);

      // Add Goiano builtin methods at the beginning
      const goianoRuntime = this.goianoBuiltins.gerarImplementacaoGoiana();
      jsCode = goianoRuntime + '\n\n' + jsCode;

      // Generate simple tokens for validation
      const tokens = this._generateTokens(code);

      return {
        success: true,
        code: jsCode,
        warnings: warnings,
        tokens: tokens,
      };
    } catch (error) {
      const goiasError = this.errorTranslator.translate(error, fileName);
      return {
        success: false,
        error: goiasError,
        code: null,
      };
    }
  }

  /**
   * Apply all necessary substitutions
   * @private
   */
  _applySubstitutions(code) {
    let result = code;

    // First, protect strings from being modified
    const stringPlaceholders = [];
    let stringIndex = 0;

    // Replace strings temporarily
    result = result.replace(/(['"])((?:(?!\1)[^\\]|\\.)*)(\1)/g, match => {
      const placeholder = `__STRING_${stringIndex++}__`;
      stringPlaceholders.push({ placeholder, original: match });
      return placeholder;
    });

    // Convert forbidden JS methods to Goiano methods first
    result = this._convertJSMethodsToGoiano(result);

    // Remove type annotations for JavaScript output
    result = this._removeTypeAnnotations(result);

    // Direct mappings ordered by size (largest first)
    const mappings = [
      // Async functions first
      ['vai_na_frente_faz_trem', 'async function'],

      // Compound operators with 'é' first
      ['é_tipo_de', 'instanceof'],
      ['é_igualim', '==='],

      // Classes and inheritance
      ['arruma_trem', 'class'],
      ['inherda_de', 'extends'],
      ['aprepara_trem', 'constructor'],
      ['num_muda', 'static'],

      // Control structures
      ['se_ocê_quiser', 'if'],
      ['se_num_for', 'else if'],
      ['se_não', 'else'],
      ['vai_indo', 'for'],
      ['enquanto_tiver', 'while'],
      ['para_com_isso', 'break'],
      ['continua_aí', 'continue'],

      // Functions
      ['faz_trem', 'function'],
      ['faz_favor', 'return'],
      ['vai_na_frente', 'async'],
      ['espera_um_cadim', 'await'],

      // Logical operators (é_igualim already above)
      ['diferente', '!=='],
      ['maior_que', '>'],
      ['menor_que', '<'],
      ['pelo_menos', '>='],
      ['no_máximo', '<='],
      ['e_mais', '&&'],
      ['ou_então', '||'],
      ['num_é', '!'],

      // Arithmetic operators
      ['mais', '+'],
      ['menos', '-'],
      ['vezes', '*'],
      ['dividido', '/'],
      ['sobrou', '%'],

      // Console and control
      ['prosa', 'console.log'],
      ['reclama', 'console.error'],

      // Promises
      ['promessa', 'Promise'],
      ['quando_resolver', 'then'],
      ['se_der_pobrema', 'catch'],
      ['resolve_aí', 'resolve'],
      ['rejeita_isso', 'reject'],

      // Try/catch
      ['tenta_aí', 'try'],
      ['se_der_ruim', 'catch'],
      ['por_fim', 'finally'],

      // Types (mais goianos!)
      ['certeza', 'true'],
      ['de_jeito_nenhum', 'false'],
      ['nada', 'null'],
      ['indefinido', 'undefined'],

      // Other simple words
      ['ocê', 'this'],
      ['faz_um', 'new'],
      ['vixe', 'throw new Error'],
      ['rejeita_isso', 'reject'],
      ['resolve_aí', 'resolve'],

      // Loop keywords
      ['em', 'in'],
      ['de', 'of'],

      // Declarations - 'é' needs to come before compound operators
      ['trem', 'var'],
      ['uai', 'const'],
      ['é', '='],
    ];

    // Apply each mapping
    mappings.forEach(([goiasWord, jsWord]) => {
      // For accented words, use a more specific approach
      if (goiasWord === 'é') {
        // Handle 'é' specially - must be between spaces
        result = result.replace(/\s+é\s+/g, ' = ');
      } else if (goiasWord === 'ocê') {
        // Handle 'ocê' which can be followed by dot or at beginning
        result = result.replace(/(^|\s)ocê(\s|\.)/g, '$1this$2');
      } else if (goiasWord.includes('_') || /[àáâãçéêí]/.test(goiasWord)) {
        // Words with underscore or accents need special treatment
        // Include common punctuation as delimiters
        const wordRegex = new RegExp(
          `(^|\\s|\\(|,|\\.)${this._escapeRegex(goiasWord)}(\\s|$|\\)|,|\\()`,
          'g',
        );
        result = result.replace(wordRegex, `$1${jsWord}$2`);
      } else {
        // Use word boundary to avoid partial substitutions
        const boundaryRegex = new RegExp(`\\b${this._escapeRegex(goiasWord)}\\b`, 'g');
        result = result.replace(boundaryRegex, jsWord);
      }
    });

    // Restore original strings
    stringPlaceholders.forEach(({ placeholder, original }) => {
      result = result.replace(placeholder, original);
    });

    return result;
  }

  /**
   * Remove type annotations from GoiásScript code for JavaScript compatibility
   * @private
   */
  _removeTypeAnnotations(code) {
    // Remove type annotations like: uai nome: texto é "value"
    // Convert to: uai nome é "value"
    return code.replace(/(uai|trem)\s+(\w+)\s*:\s*\w+\s+(é)/g, '$1 $2 $3');
  }

  /**
   * Convert JavaScript methods to Goiano methods
   * @private
   */
  _convertJSMethodsToGoiano(code) {
    let result = code;

    // String methods
    result = result.replace(/\.replace\s*\(/g, '.trocar(');
    result = result.replace(/\.split\s*\(/g, '.dividir(');
    result = result.replace(/\.join\s*\(/g, '.juntar(');
    result = result.replace(/\.toUpperCase\s*\(\)/g, '.pra_maiusculo()');
    result = result.replace(/\.toLowerCase\s*\(\)/g, '.pra_minusculo()');
    result = result.replace(/\.trim\s*\(\)/g, '.aparar()');
    result = result.replace(/\.includes\s*\(/g, '.contem(');
    result = result.replace(/\.indexOf\s*\(/g, '.posicao_de(');
    result = result.replace(/\.substring\s*\(/g, '.pedaco(');
    result = result.replace(/\.slice\s*\(/g, '.fatiar(');
    result = result.replace(/\.charAt\s*\(/g, '.letra_em(');
    result = result.replace(/\.length\b/g, '.tamanho()');
    result = result.replace(/\.startsWith\s*\(/g, '.comeca_com(');
    result = result.replace(/\.endsWith\s*\(/g, '.termina_com(');

    // Array methods
    result = result.replace(/\.map\s*\(/g, '.mapear(');
    result = result.replace(/\.filter\s*\(/g, '.filtrar(');
    result = result.replace(/\.reduce\s*\(/g, '.reduzir(');
    result = result.replace(/\.forEach\s*\(/g, '.pra_cada(');
    result = result.replace(/\.push\s*\(/g, '.empurrar(');
    result = result.replace(/\.pop\s*\(\)/g, '.tirar_ultimo()');
    result = result.replace(/\.shift\s*\(\)/g, '.tirar_primeiro()');
    result = result.replace(/\.unshift\s*\(/g, '.por_primeiro(');
    result = result.replace(/\.sort\s*\(/g, '.ordenar(');
    result = result.replace(/\.reverse\s*\(\)/g, '.inverter()');
    result = result.replace(/\.find\s*\(/g, '.achar(');
    result = result.replace(/\.concat\s*\(/g, '.juntar_lista(');
    result = result.replace(/\.splice\s*\(/g, '.emendar(');

    // Object methods
    result = result.replace(/Object\.keys\s*\(/g, 'Object.chaves(');
    result = result.replace(/Object\.values\s*\(/g, 'Object.valores(');
    result = result.replace(/Object\.entries\s*\(/g, 'Object.entradas(');
    result = result.replace(/\.hasOwnProperty\s*\(/g, '.tem_propriedade(');
    result = result.replace(/Object\.assign\s*\(/g, 'Object.misturar(');

    // Math methods
    result = result.replace(/Math\.random\s*\(\)/g, 'GoianoMath.sorteio()');
    result = result.replace(/Math\.floor\s*\(/g, 'GoianoMath.arredondar_baixo(');
    result = result.replace(/Math\.ceil\s*\(/g, 'GoianoMath.arredondar_cima(');
    result = result.replace(/Math\.round\s*\(/g, 'GoianoMath.arredondar(');
    result = result.replace(/Math\.max\s*\(/g, 'GoianoMath.maior(');
    result = result.replace(/Math\.min\s*\(/g, 'GoianoMath.menor(');
    result = result.replace(/Math\.abs\s*\(/g, 'GoianoMath.absoluto(');
    result = result.replace(/Math\.sqrt\s*\(/g, 'GoianoMath.raiz_quadrada(');
    result = result.replace(/Math\.pow\s*\(/g, 'GoianoMath.potencia(');
    result = result.replace(/Math\.PI\b/g, 'GoianoMath.PI');
    result = result.replace(/Math\.E\b/g, 'GoianoMath.E');

    // Global functions
    result = result.replace(/parseInt\s*\(/g, 'vira_numero(');
    result = result.replace(/parseFloat\s*\(/g, 'vira_decimal(');
    result = result.replace(/isNaN\s*\(/g, 'eh_nao_numero(');
    result = result.replace(/setTimeout\s*\(/g, 'depois_de(');
    result = result.replace(/setInterval\s*\(/g, 'repetir_a_cada(');
    result = result.replace(/clearTimeout\s*\(/g, 'cancelar_depois(');
    result = result.replace(/clearInterval\s*\(/g, 'cancelar_repeticao(');

    // Console methods
    result = result.replace(/console\.log\s*\(/g, 'prosa(');
    result = result.replace(/console\.error\s*\(/g, 'prosa_erro(');
    result = result.replace(/console\.warn\s*\(/g, 'prosa_aviso(');

    return result;
  }

  /**
   * Check for forbidden non-Goiano methods
   * @private
   */
  _checkForbiddenMethods(code) {
    const warnings = [];
    const forbiddenMethods = [
      '.replace(',
      '.split(',
      '.join(',
      '.toUpperCase()',
      '.toLowerCase()',
      '.map(',
      '.filter(',
      '.reduce(',
      '.forEach(',
      '.push(',
      '.pop()',
      'Math.random()',
      'Math.floor(',
      'console.log(',
      'parseInt(',
      'setTimeout(',
    ];

    forbiddenMethods.forEach(method => {
      if (code.includes(method)) {
        const goianoEquivalent = this.goianoBuiltins.converterParaGoiano(
          method.replace(/[()]/g, ''),
        );
        warnings.push({
          type: 'forbidden_method',
          message: `⚠️ Ô sô! O método "${method}" não é goiano não! Use "${goianoEquivalent}" que é mais da hora.`,
          suggestion: `Troca esse ${method} por .${goianoEquivalent}(`,
        });
      }
    });

    return warnings;
  }

  /**
   * Validate basic syntax patterns
   * @private
   */
  _validateSyntax(code) {
    const errors = [];
    const lines = code.split('\n');

    lines.forEach((line, index) => {
      const trimmed = line.trim();
      if (trimmed && !trimmed.startsWith('//')) {
        // Simple check for obvious syntax errors
        if (trimmed.includes('{{{') || trimmed.includes('}}}')) {
          errors.push({
            message: `Erro de sintaxe na linha ${index + 1}: Chaves desbalanceadas`,
            type: 'syntax_error',
            line: index + 1,
          });
        }

        // Check for incomplete variable declarations.
        // Aceita 'uai x é valor', 'uai x = valor' (forma JS) e
        // desestruturação 'uai { a, b } = obj' / 'uai [a, b] = lista'.
        // Falso-positivo conhecido da v2 corrigido aqui — a validação real
        // é feita pelo lexer/transpiler abaixo.
        if (
          trimmed.startsWith('uai ') &&
          !trimmed.includes(' é ') &&
          !trimmed.includes(' = ') &&
          !trimmed.includes('{') &&
          !trimmed.includes('[')
        ) {
          errors.push({
            message: `Erro de sintaxe na linha ${index + 1}: Declaração de variável incompleta`,
            type: 'syntax_error',
            line: index + 1,
          });
        }
      }
    });

    return errors;
  }

  /**
   * Generate simple tokens for validation
   * @private
   */
  _generateTokens(code) {
    const tokens = [];
    const lines = code.split('\n');

    lines.forEach((line, index) => {
      const trimmed = line.trim();
      if (trimmed && !trimmed.startsWith('//')) {
        // Simple tokenization - split on spaces and common separators
        const words = trimmed.split(/[\s\(\)\{\}\[\];,\.]+/).filter(w => w.length > 0);
        words.forEach(word => {
          tokens.push({
            type: this._getTokenType(word),
            value: word,
            line: index + 1,
          });
        });
      }
    });

    return tokens;
  }

  /**
   * Get token type for simple validation
   * @private
   */
  _getTokenType(word) {
    const keywords = [
      'uai',
      'trem',
      'faz_trem',
      'prosa',
      'faz_favor',
      'se',
      'senao',
      'pra',
      'enquanto',
    ];
    if (keywords.includes(word)) return 'keyword';
    if (/^\d+(\.\d+)?$/.test(word)) return 'number';
    if (/^["'].*["']$/.test(word)) return 'string';
    if (/^[a-zA-Z_][a-zA-Z0-9_]*$/.test(word)) return 'identifier';
    return 'symbol';
  }

  /**
   * Escape special characters for regex
   * @private
   */
  _escapeRegex(string) {
    return string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  }
}

